export interface Workshop { id: number; title: string; roomCode: string; }
export interface WorkshopRow { key: string; label: string; room: string; }
export interface WorkshopFilter { text: string; room: string | null; }
export type WorkshopLoader = () => Promise<readonly Workshop[]>;
export type WorkshopMapper = (workshop: Workshop) => WorkshopRow;
export type AddWorkshopDialog = () => Promise<boolean>;
export type ErrorReporter = (error: unknown) => void;

type FilterListener = (filter: WorkshopFilter) => void;
type Subscription = { listener: FilterListener };

function copyWorkshop(workshop: Workshop): Workshop {
  return { id: workshop.id, title: workshop.title, roomCode: workshop.roomCode };
}

function copyRow(row: WorkshopRow): WorkshopRow {
  return { key: row.key, label: row.label, room: row.room };
}

function copyFilter(filter: WorkshopFilter): WorkshopFilter {
  return { text: filter.text, room: filter.room };
}

export class WorkshopToolbar {
  private rows: WorkshopRow[] = [];
  private readonly subscriptions: Subscription[] = [];

  constructor(
    private readonly loader: WorkshopLoader,
    private readonly mapper: WorkshopMapper,
    private readonly dialog: AddWorkshopDialog,
    private readonly reportError: ErrorReporter,
  ) {}

  subscribe(listener: FilterListener): () => void {
    const subscription: Subscription = { listener };
    this.subscriptions.push(subscription);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const index = this.subscriptions.indexOf(subscription);
      if (index >= 0) this.subscriptions.splice(index, 1);
    };
  }

  emitFilter(filter: WorkshopFilter): void {
    for (const subscription of [...this.subscriptions]) {
      subscription.listener(copyFilter(filter));
    }
  }

  getRows(): WorkshopRow[] {
    return this.rows.map(copyRow);
  }

  async initialize(): Promise<boolean> {
    try {
      const workshops = await this.loader();
      const next = workshops.map(workshop => copyRow(this.mapper(copyWorkshop(workshop))));
      this.rows = next;
      return true;
    } catch (error) {
      this.reportError(error);
      return false;
    }
  }

  async openAddDialog(): Promise<boolean> {
    try {
      if (!(await this.dialog())) return false;
    } catch (error) {
      this.reportError(error);
      return false;
    }
    if (!(await this.initialize())) return false;
    this.emitFilter({ text: "", room: null });
    return true;
  }
}
